// Exercises the committed test fixture at tests/fixtures/dataset/ (regenerated by
// tools/build_client_fixture_dataset.py -- see that script's own docstring). This is NOT a
// pipeline test: it proves the fixture itself is shaped the way the client's loader
// (`src/dataset.ts`) and renderer (`src/main.ts`) actually expect -- the positional
// node/edge-geometry contract, and that every curated shape the fixture claims to cover
// (a gate, a repeatable, a weight-modifier swap pair, an alternative group, one technology per
// availability state) really is present in the committed data, so a future client feature can
// rely on this fixture without re-deriving any of that by hand.

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import type { BaseDataset, DetailPayload, EmpireOverlay } from "../../schema/generated/dataset-types";

const FIXTURE_DIR = join(__dirname, "fixtures/dataset");

function readJson<T>(name: string): T {
  return JSON.parse(readFileSync(join(FIXTURE_DIR, name), "utf-8")) as T;
}

interface FixtureManifest {
  baseDataset: string;
  searchIndex: string;
  diagnostics: string;
  overlays: Record<string, string>;
  details: Record<string, string>;
  curatedIds: Record<string, string>;
}

const manifest = readJson<FixtureManifest>("manifest.json");
const base = readJson<BaseDataset>(manifest.baseDataset);

describe("fixture base dataset", () => {
  it("has at least one technology and edge", () => {
    expect(base.technologies.length).toBeGreaterThan(0);
    expect(base.edges.length).toBeGreaterThan(0);
  });

  it("declares node-positions geometry length matching 2 floats per technology", () => {
    expect(base.geometry.nodePositions.length).toBe(base.technologies.length * 2);
  });

  it("declares edge-polylines geometry length matching 12 floats per edge (6 waypoints)", () => {
    expect(base.geometry.edgePolylines.length).toBe(base.edges.length * 12);
  });

  it("has a node-positions side-file with exactly the declared number of float32 elements", () => {
    const bytes = readFileSync(join(FIXTURE_DIR, "node-positions.f32"));
    expect(bytes.byteLength / 4).toBe(base.geometry.nodePositions.length);
  });

  it("has an edge-polylines side-file with exactly the declared number of float32 elements", () => {
    const bytes = readFileSync(join(FIXTURE_DIR, "edge-polylines.f32"));
    expect(bytes.byteLength / 4).toBe(base.geometry.edgePolylines.length);
  });

  it("every edge references two technologies that are both present in this fixture", () => {
    const ids = new Set(base.technologies.map((t) => t.id));
    for (const edge of base.edges) {
      expect(ids.has(edge.from)).toBe(true);
      expect(ids.has(edge.to)).toBe(true);
    }
  });
});

describe("fixture curated shapes", () => {
  const byId = new Map(base.technologies.map((t) => [t.id, t]));

  it("covers a gated technology with a negative (Unavailable to X) gate", () => {
    const tech = byId.get(manifest.curatedIds.gated)!;
    expect(tech.gates.length).toBeGreaterThan(0);
    expect(tech.gates.some((g) => g.negated)).toBe(true);
  });

  it("covers a repeatable technology", () => {
    const tech = byId.get(manifest.curatedIds.repeatable)!;
    expect(tech.repeatable).not.toBeNull();
  });

  it("covers an alternative-group edge", () => {
    const groupTechId = manifest.curatedIds.alternative_group;
    const altEdges = base.edges.filter((e) => e.to === groupTechId && e.kind === "alternative");
    expect(altEdges.length).toBeGreaterThan(0);
    expect(altEdges.every((e) => e.groupId !== null)).toBe(true);
  });

  it("covers the housing weight-modifier swap pair with strictly opposite gate polarity", () => {
    const a = byId.get(manifest.curatedIds.weight_modifier_pair_a)!;
    const b = byId.get(manifest.curatedIds.weight_modifier_pair_b)!;
    const gateA = a.gates.find((g) => g.refId === "civic_agrarian_idyll");
    const gateB = b.gates.find((g) => g.refId === "civic_agrarian_idyll");
    expect(gateA).toBeDefined();
    expect(gateB).toBeDefined();
    expect(gateA!.negated).not.toBe(gateB!.negated);
  });

  it("covers one technology per availability state (profile index 0)", () => {
    const states = ["available", "locked", "uncertain", "config-gated", "weight-gated"] as const;
    for (const state of states) {
      const id = manifest.curatedIds[`state_${state}`];
      expect(id, `no curated id recorded for state ${state}`).toBeDefined();
      const tech = byId.get(id!)!;
      expect(tech.availabilityMatrix[0]).toBe(state);
    }
  });

  it("has a detail payload for the weight-modifier technology carrying a real weight_modifier", () => {
    const id = manifest.curatedIds.weight_modifier_pair_a;
    const detail = readJson<DetailPayload>(manifest.details[id]!);
    expect(detail.technologyId).toBe(id);
    expect(detail.weight.modifiers.length).toBeGreaterThan(0);
  });

  it("has a detail payload with a non-empty variants list for the variants technology, if one was found", () => {
    const id = manifest.curatedIds.variants;
    if (!id) return; // real corpus may not always yield one; the build script tolerates that
    const detail = readJson<DetailPayload>(manifest.details[id]!);
    expect(detail.variants.length).toBeGreaterThan(0);
  });
});

describe("fixture empire overlays", () => {
  it("every declared overlay validates against the base dataset's technology set", () => {
    const ids = new Set(base.technologies.map((t) => t.id));
    for (const path of Object.values(manifest.overlays)) {
      const overlay = readJson<EmpireOverlay>(path);
      for (const techId of Object.keys(overlay.availability)) {
        expect(ids.has(techId)).toBe(true);
      }
    }
  });
});
